@ContinuousAt.eventually_lt : ∀ {α : Type u_1} {β : Type u_2} [inst : TopologicalSpace α] [inst_1 : LinearOrder α]
  [OrderClosedTopology α] {f g : β → α} [inst_3 : TopologicalSpace β] {x₀ : β},
  ContinuousAt f x₀ → ContinuousAt g x₀ → f x₀ < g x₀ → ∀ᶠ (x : β) in nhds x₀, f x < g x

@mem_nhdsGE_iff_exists_Icc_subset : ∀ {α : Type u_1} [inst : TopologicalSpace α] [inst_1 : LinearOrder α]
  [OrderTopology α] [NoMaxOrder α] [DenselyOrdered α] {a : α} {s : Set α},
  s ∈ nhdsWithin a (Set.Ici a) ↔ ∃ u, a < u ∧ Set.Icc a u ⊆ s

@Filter.Eventually.exists_Ioo_subset : ∀ {α : Type u_1} [inst : TopologicalSpace α] [inst_1 : LinearOrder α]
  [OrderTopology α] [NoMaxOrder α] [NoMinOrder α] {a : α} {p : α → Prop},
  (∀ᶠ (x : α) in nhds a, p x) → ∃ l u, a ∈ Set.Ioo l u ∧ Set.Ioo l u ⊆ {x | p x}
